// ============================================================
// PREPARAR FOTO BINARIA — WF1
// Última actualización: 03/11/2026 (sesión 21) — contrato v1, paso 4
// Antes: 27/10/2026 (sesión 20) — 16.39, capa (b)
// ------------------------------------------------------------
// Desde el paso 4 la foto se sube DESPUÉS de registrar la lectura. Este nodo ya
// no recibe la salida del Motor por su entrada (le llega la respuesta de
// `fn_registrar_telemetria`), así que lee los datos de `Consolidar datos`, que
// además ya decidió el nombre de la foto (path_foto_evento).
//
// 16.39: `undefined` en un campo binario no es un error de JavaScript: sin esta
// guarda, el nodo terminaba en verde con `data: undefined` y la ejecución moría un
// nodo más abajo, en `Subir Foto a Storage`. Una salida que se olvide la foto
// falla acá, con el nombre de la causa.
// ============================================================
const d = $('Consolidar datos').item.json;

const fotoBase64 = d.foto_base64;
if (!fotoBase64) {
  throw new Error(
    'Preparar Foto binaria: llegó un ítem con tiene_foto=true pero sin foto_base64. ' +
    'Es una salida incompleta del Motor de Inferencia, no un problema de Storage (16.39). ' +
    `estado="${d.estado}" lectura_sospechosa=${d.lectura_sospechosa}`
  );
}
if (!d.path_foto_evento) {
  throw new Error(
    'Preparar Foto binaria: Consolidar datos no armó path_foto_evento para una lectura con foto ' +
    '— falta actualizar Consolidar datos (contrato v1, paso 4).'
  );
}

return [{
  json: { ...d },
  binary: {
    data: {
      data: fotoBase64,
      mimeType: 'image/jpeg',
      fileName: d.path_foto_evento.split('/').pop()
    }
  }
}];

// ============================================================
// CONSOLIDAR DATOS — WF1
// Última actualización: 03/11/2026 (sesión 21) — contrato v1, pasos 4 y 5 (16.47, 16.48)
// Antes: 16/10/2026 (sesión 16) — incluye 16.34 y 13.7.2
// ------------------------------------------------------------
// Desde el paso 4 este nodo corre ANTES de la foto: primero se registra la
// lectura (con su DNI), después se hace todo lo demás. Así, un reintento que la
// base marca como duplicado no vuelve a subir la foto, y una falla de Storage
// ya no se lleva la lectura con ella.
// ============================================================
const motor = $('Motor de Inferencia').item.json;

// ============================================================
// LA LECTURA NORMALIZADA DE LA PUERTA (`Validar Contrato`)
// ------------------------------------------------------------
// De ahí salen los datos que el Motor no usa para decidir y por eso no emite:
// el DNI de la lectura (arranque_id, seq), la hora de la placa (ts), el motivo
// (paso 4) y la temperatura y la conductividad (paso 5). Ya llegan validados.
// Validación positiva: si la puerta no emitió alguno, es una versión vieja de
// `Validar Contrato`, y guardar sin ellos perdería el dato callado.
// ============================================================
const lectura = $('Validar Contrato').first().json.lectura;
const CAMPOS_LECTURA = ['arranque_id', 'seq', 'ts', 'motivo', 'temperatura', 'conductividad'];
const faltan = lectura ? CAMPOS_LECTURA.filter(k => !(k in lectura)) : CAMPOS_LECTURA;
if (faltan.length > 0) {
  throw new Error(
    `Consolidar datos: la lectura de Validar Contrato no trae ${faltan.join(', ')} ` +
    '— falta actualizar Validar Contrato (contrato v1, pasos 4 y 5).'
  );
}

// ============================================================
// EL NOMBRE DE LA FOTO SE DECIDE ACÁ, UNA SOLA VEZ
// ------------------------------------------------------------
// Antes lo armaba `Preparar Foto binaria`, que corría antes que este nodo.
// Ahora la foto va después, y WF2 (que recibe la salida de este nodo) necesita
// el mismo nombre para guardarlo en su diagnóstico. `Preparar Foto binaria`,
// `Subir Foto a Storage` y `Actualizar Ultima Foto Cultivo` usan este.
// ============================================================
const pathFotoEvento = motor.tiene_foto === true
  ? `${motor.cultivo_id}/${Date.now()}.jpg`
  : null;

// ============================================================
// 16.34 — EL CUERPO DE LA RPC SE ARMA COMO OBJETO, NUNCA CONCATENANDO TEXTO
// ------------------------------------------------------------
// `fn_registrar_telemetria` declara sus métricas como DEFAULT NULL y filtra con
// `WHERE v.valor IS NOT NULL`: acepta lecturas parciales POR DISEÑO. El nodo que la
// llamaba armaba el JSON interpolando texto, así que un sensor que no reportaba
// dejaba el cuerpo como `"p_humedad": ,` — JSON inválido, telemetría perdida entera.
// Acá el cliente pasa a poder expresar lo que la base ya sabía recibir.
// ============================================================

// OJO con la coerción: Number(null) === 0 y Number('') === 0.
// Un sensor ausente convertido a 0 no es un dato faltante: es una lectura de 0%
// de humedad, que el Motor interpreta como sequía y que dispara riego real.
// Por eso la ausencia se decide ANTES de convertir, nunca después.
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const rpcTelemetria = {
  p_cultivo_id:     motor.cultivo_id,
  p_dispositivo_id: motor.dispositivo_id,
  // El DNI y la hora de la placa (paso 4). Con un DNI repetido la base no guarda
  // nada y devuelve duplicada = true: WF1 responde "duplicada", sin avisar ni regar.
  p_arranque_id:   lectura.arranque_id,
  p_seq:           lectura.seq,
  p_ts:            lectura.ts,
  p_motivo:        lectura.motivo,
  p_humedad:       num(motor.humedad),
  p_ph:            num(motor.ph),
  p_n:             num(motor.n),
  p_p:             num(motor.p),
  p_k:             num(motor.k),
  p_temperatura:   num(lectura.temperatura),
  p_conductividad: num(lectura.conductividad)
};

// Validación positiva, no negativa: se verifica afirmativamente que están los dos
// campos de identidad. Una fila de telemetría sin cultivo es peor que una perdida,
// porque queda en la base y miente.
if (!rpcTelemetria.p_cultivo_id || !rpcTelemetria.p_dispositivo_id) {
  throw new Error(
    'Consolidar datos: falta cultivo_id o dispositivo_id — no se registra telemetría sin identidad. ' +
    `mac=${motor.mac_address ?? 'desconocida'}`
  );
}

// ============================================================
// 13.7.2 — CUERPO DE fn_registrar_recheck_riego, también como objeto (16.34)
// ------------------------------------------------------------
// `Registrar Recheck de Riego` llama en CADA lectura: si esta lectura no es un
// recheck, va p_evento_id null y la función no hace nada. Así no hace falta un
// IF que abra una rama paralela en el camino principal.
// Validación positiva: el Motor tiene que haber emitido el campo, aunque sea null.
// Si falta, el Motor es una versión vieja y el freno de riego no funciona.
// ============================================================
if (!('recheck_riego' in motor)) {
  throw new Error('Consolidar datos: el Motor no emitió recheck_riego — falta actualizar el Motor de Inferencia (13.7.2).');
}
const rc = motor.recheck_riego;
const rpcRecheck = {
  p_cultivo_id: motor.cultivo_id,
  p_evento_id:  rc ? rc.evento_id : null,
  p_humedad:    rc ? rc.humedad   : null,
  p_resultado:  rc ? rc.resultado : null
};

// Cuántas métricas trae realmente esta lectura (= cuántas filas de medición va a
// escribir la RPC). Con 0, la lectura igual queda registrada (sin mediciones).
const metricasPresentes = ['p_humedad', 'p_ph', 'p_n', 'p_p', 'p_k', 'p_temperatura', 'p_conductividad']
  .filter(k => rpcTelemetria[k] !== null).length;

return [{
  json: {
    ...motor,
    path_foto_evento: pathFotoEvento,
    rpc_telemetria: rpcTelemetria,
    rpc_recheck: rpcRecheck,
    metricas_presentes: metricasPresentes
  }
}];

// ============================================================
// VALIDAR CONTRATO — WF1 · contrato de telemetría v1, paso 2
// Escrito el 19/10/2026 (sesión 17). Cierra 16.52.
// ------------------------------------------------------------
// La puerta del sistema. Corre ANTES de `Resolver Cultivo`, o sea antes del
// primer nodo que decide. Hace dos cosas, una sola vez:
//   1. VALIDA el cuerpo contra docs/contrato_telemetria.md (secciones 2 y 3).
//      Si algo no cumple, la lectura se rechaza ENTERA y se informa cada campo
//      con problema: una lectura mal formada no puede disparar un riego.
//   2. NORMALIZA: arma `lectura`, el único objeto que leen los nodos de abajo.
//      Nadie aguas abajo vuelve a leer el cuerpo crudo del Webhook.
//
// 16.52: el Motor comparaba el valor crudo, y en JavaScript `"" < 60` es true
// (la cadena vacía se convierte a 0): un sensor sin dato era SEQUÍA y regaba.
// La normalización existía, pero vivía en `Consolidar datos`, DESPUÉS del
// Motor. Normalizar en el borde quiere decir el borde del SISTEMA, no el de la
// función que se estaba tocando.
//
// Lo que NO se valida acá: que el arranque_id sea de esta placa. Eso es un
// dato de la base y lo verifica el nodo siguiente, `Verificar Arranque`.
// ============================================================
const VERSION_CONTRATO = 1;
const MAC_RE = /^[0-9A-F]{2}(:[0-9A-F]{2}){5}$/i;

// Rango FÍSICO del sensor (contrato, regla 2): límites de lo POSIBLE, no de lo
// sano (lo sano lo deciden los umbrales de la etapa). Un valor afuera tenía que
// llegar como null; si llega el número, la placa no cumple el contrato.
const MEDICIONES = {
  humedad:       [0, 100],
  temperatura:   [-40, 80],
  ph:            [0, 14],
  conductividad: [0, 20],
  n:             [0, 2000],
  p:             [0, 2000],
  k:             [0, 2000],
};
const MOTIVOS = ['programada', 'recheck'];

const crudo = $('Webhook').first().json.body;
const esObjeto = crudo !== null && typeof crudo === 'object' && !Array.isArray(crudo);
const b = esObjeto ? crudo : {};
const errores = [];
const tiene = (k) => Object.prototype.hasOwnProperty.call(b, k);
const esEntero = (x) => typeof x === 'number' && Number.isSafeInteger(x);
const mostrar = (x) => JSON.stringify(x) ?? String(x);

if (!esObjeto) {
  errores.push('cuerpo: tiene que ser un objeto JSON');
} else if (tiene('v') && b.v !== VERSION_CONTRATO) {
  // Otra versión: el resto del cuerpo puede significar otra cosa. No se lo
  // revisa campo por campo, porque esos errores serían ruido.
  errores.push(`v: versión ${mostrar(b.v)} desconocida; este servidor entiende la ${VERSION_CONTRATO}`);
} else {
  if (!tiene('v')) errores.push('v: falta');

  // dispositivo_mac — se normaliza a mayúsculas, como está en la base.
  if (!tiene('dispositivo_mac')) errores.push('dispositivo_mac: falta');
  else if (typeof b.dispositivo_mac !== 'string' || !MAC_RE.test(b.dispositivo_mac.trim()))
    errores.push(`dispositivo_mac: ${mostrar(b.dispositivo_mac)} no tiene el formato AA:BB:CC:DD:EE:FF`);

  // arranque_id y seq — el DNI de la lectura (contrato, regla 3).
  if (!tiene('arranque_id')) errores.push('arranque_id: falta');
  else if (!esEntero(b.arranque_id) || b.arranque_id < 1)
    errores.push(`arranque_id: ${mostrar(b.arranque_id)} no es un entero positivo`);

  if (!tiene('seq')) errores.push('seq: falta');
  else if (!esEntero(b.seq) || b.seq < 0)
    errores.push(`seq: ${mostrar(b.seq)} no es un entero mayor o igual a 0`);

  // ts — obligatorio, pero puede ser null (la placa no tiene hora confiable).
  if (!tiene('ts')) errores.push('ts: falta (si la placa no tiene hora, mandar null)');
  else if (b.ts !== null && (!esEntero(b.ts) || b.ts < 0))
    errores.push(`ts: ${mostrar(b.ts)} no es un entero (segundos Unix) ni null`);

  if (!tiene('motivo')) errores.push('motivo: falta');
  else if (!MOTIVOS.includes(b.motivo))
    errores.push(`motivo: ${mostrar(b.motivo)} no es "programada" ni "recheck"`);

  // Las 7 mediciones: siempre presentes; número dentro del rango físico, o null.
  // La ausencia se declara en el origen, no se adivina acá (contrato, regla 1).
  for (const [campo, [min, max]] of Object.entries(MEDICIONES)) {
    if (!tiene(campo)) {
      errores.push(`${campo}: falta (si el sensor no pudo medir, mandar null)`);
    } else if (b[campo] === null) {
      // válido: "el sensor no pudo medir esta variable"
    } else if (typeof b[campo] !== 'number' || !Number.isFinite(b[campo])) {
      errores.push(`${campo}: ${mostrar(b[campo])} no es un número ni null`);
    } else if (b[campo] < min || b[campo] > max) {
      errores.push(`${campo}: ${b[campo]} está fuera del rango físico del sensor (${min} a ${max}); un valor imposible se manda como null`);
    }
  }

  // foto_base64 — opcional. Si no hay foto, el campo NO se manda.
  if (tiene('foto_base64') && (typeof b.foto_base64 !== 'string' || b.foto_base64.trim() === ''))
    errores.push('foto_base64: si se manda, tiene que ser texto no vacío (sin foto, no mandar el campo)');

  // Campos que el contrato no conoce (p. ej. el viejo `planta`): se ignoran (regla 6).
}

const contratoOk = errores.length === 0;

// La lectura normalizada: solo los campos del contrato, con sus tipos.
const lectura = contratoOk ? {
  dispositivo_mac: b.dispositivo_mac.trim().toUpperCase(),
  arranque_id:     b.arranque_id,
  seq:             b.seq,
  ts:              b.ts,
  motivo:          b.motivo,
  humedad:         b.humedad,
  temperatura:     b.temperatura,
  ph:              b.ph,
  conductividad:   b.conductividad,
  n:               b.n,
  p:               b.p,
  k:               b.k,
  ...(tiene('foto_base64') ? { foto_base64: b.foto_base64.trim() } : {}),
} : null;

// Lo que se guarda si se rechaza: el cuerpo SIN la foto, con un tope de tamaño.
const { foto_base64: _foto, ...sinFoto } = b;
let cuerpo = tiene('foto_base64') ? { ...sinFoto, foto_base64: '[omitida]' } : sinFoto;
if (!esObjeto) cuerpo = { _no_es_objeto: mostrar(crudo).slice(0, 500) };
if (JSON.stringify(cuerpo).length > 8000) cuerpo = { _truncado: true, claves: Object.keys(b).slice(0, 50) };

return [{
  json: {
    contrato_ok: contratoOk,
    errores,
    lectura,
    registro: {
      mac:    typeof b.dispositivo_mac === 'string' ? b.dispositivo_mac.slice(0, 64) : null,
      cuerpo,
    },
  },
}];

// ============================================================
// RESULTADO DE LA FOTO — WF1
// Escrito el 03/11/2026 (sesión 21). Aislamiento de fallos de Storage.
// ------------------------------------------------------------
// Hasta el 03/11, si `Subir Foto a Storage` fallaba, el workflow se detenía ahí:
// la lectura ya estaba guardada, pero no salían el Telegram ni el riego. Por no
// poder ARCHIVAR una foto, la planta se quedaba sin riego y nadie se enteraba.
// Ahora ese nodo sale por su salida de error hasta acá, y el flujo sigue.
//
// A este nodo llegan los tres caminos:
//   - la lectura no traía foto           → foto_guardada = null
//   - la foto se subió y se marcó        → foto_guardada = true
//   - Storage falló (salida de error)    → foto_guardada = false
//
// La IA no necesita Storage: WF2 recibe la foto dentro del pedido. Lo único que
// se pierde es la copia (historial y WF3). Por eso a WF2 se le pasa la foto como
// NO guardada (path null), para que su diagnóstico no apunte a un archivo que no
// existe.
//
// Un fallo manejado tiene que seguir siendo contado: con foto_guardada = false,
// `Foto no guardada?` manda un Telegram aparte, haya alerta o no.
// ============================================================
const cons = $('Consolidar datos').item.json;
const lecturaId = $('fn_registrar_telemetria').item.json.lectura_id ?? null;

let fotoGuardada = null;
let fotoError = null;

if (cons.tiene_foto === true) {
  if ($json.error !== undefined) {
    // Salida de error de `Subir Foto a Storage`.
    fotoGuardada = false;
    const e = $json.error;
    fotoError = String(typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e))).slice(0, 300);
  } else if ($json.ultima_foto_path === cons.path_foto_evento) {
    // Validación positiva: `Actualizar Ultima Foto Cultivo` devolvió el cultivo
    // con ESTE path. No alcanza con "no hubo error".
    fotoGuardada = true;
  } else {
    fotoGuardada = false;
    fotoError = 'Actualizar Ultima Foto Cultivo no devolvió el path de esta foto ' +
      `(esperado "${cons.path_foto_evento}", recibido "${$json.ultima_foto_path ?? 'nada'}")`;
  }
}

return [{
  json: {
    lectura_id: lecturaId,
    foto_guardada: fotoGuardada,
    aviso_foto: fotoGuardada === false,   // siempre booleano: lo lee un IF estricto
    foto_error: fotoError,
    path_foto_guardada: fotoGuardada === true ? cons.path_foto_evento : null
  }
}];

